    if (array == null) {
        throw new NullPointerException("Input array cannot be null");
    }

    // Initialize a boolean array to hold the primitive values
    boolean[] primitiveArray = new boolean[array.length];

    // Iterate through the Boolean array
    for (int i = 0; i < array.length; i++) {
        // Check if the element is null
        if (array[i] == null) {
            // Throw a NullPointerException if any element is null
            throw new NullPointerException("Null element found in the array");
        } else {
            // Convert the Boolean to boolean and add to the primitive array
            primitiveArray[i] = array[i].booleanValue();
        }
    }

    // Return the primitive array
    return primitiveArray;
}

