    int newCapacity = capacity() + size;

    // Create a new byte array with increased capacity
    byte[] newBuffer = new byte[newCapacity];

    // Copy all existing bytes from the original buffer to the new buffer
    System.arraycopy(buffer, 0, newBuffer, 0, capacity());

    // Assign the new buffer to the instance variable
    buffer = newBuffer;
}

