        throw new IllegalArgumentException("Invalid index range for type writing");
    }

    StackMapTableAttribute stackMapTable = (StackMapTableAttribute) currentFrame.getAttribute(AttributeType.STACK_MAP_TABLE);
    if (stackMapTable == null) {
        stackMapTable = new StackMapTableAttribute(currentFrame.getMajorVersion());
        currentFrame.addAttribute(stackMapTable);
    }

    int typeCount = stackMapTable.getNumberOfLocals();
    if (typeCount < start + end) {
        typeCount = start + end;
    }

    for (int i = start; i < end; i++) {
        boolean abstractType = (currentFrame.getType(i) instanceof AbstractType);
        int signatureIndex = abstractType ? abstractType.getTypeIndex() : 0;

        stackMapTable.addAttribute(new AbstractTypeAttribute(typeCount, signatureIndex));
        typeCount++;
    }
}

