    }

    // Check if the substring is empty or the target index is the same as the index of the substring
    if (substring == null || substring.length() == 0 || index == substring.length()) {
        return false;
    }

    // Compare each character of the substring with the corresponding character at the target index
    for (int i = 0; i < substring.length(); i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }

    return true;
}

