private void writeToClients(LoggingEvent event){
    // Check if there are any connected clients
    if (connectedClients == null || connectedClients.isEmpty()) {
        return; // No clients connected, so do nothing
    }

    StringBuilder message = new StringBuilder();
    message.append(event.getLevel().toString());
    message.append(" - ");
    message.append(event.getMessage());

    // Send the message to each client
    for (Socket-client : connectedClients) {
        try {
           OutputStream outputStream = client.getOutputStream();
            byte[] messageBytes = message.toString().getBytes();
            outputStream.write(messageBytes);
            outputStream.flush();
        } catch (IOException e) {
            e.printStackTrace();
            connectedClients.remove(client); // Remove the client from connectedClients if there's an issue
        }
    }
}

