public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Check if dayStep is not greater than 6
    if (dayStep > 6) {
        throw new IllegalArgumentException("dayStep cannot be greater than 6");
    }
    // Clamp timeBucket within a reasonable range to avoid overflow or underflow
    timeBucket = Math.max(1, Math.min(timeBucket, Math.pow(10, 18)));

    // Check if timeBucket is a multiple of dayStep
    if (timeBucket % dayStep != 0) {
        throw new IllegalArgumentException("timeBucket must be a multiple of dayStep");
    }

    // Special case for dayStep of 1
    if (dayStep == 1) {
        return (timeBucket / dayStep) * dayStep;
    } else {
        // Apply the dayStep compaction logic
        long start = timeBucket - (timeBucket % dayStep);
        return start + (start % dayStep - timeBucket % dayStep) * (dayStep - 1);
    }
}

