public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    // Check if the file exists
    if (!file.exists()) {
        throw new IllegalArgumentException("File not found: " + file.getAbsolutePath());
    }

    // Check if the file is a regular file
    if (!file.isFile()) {
        throw new IllegalArgumentException("The provided path does not point to a file.");
    }

    // Initialize the list to store thread snapshots
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

    // Open the file for reading
    try (FileInputStream fis = new FileInputStream(file);
         ObjectInputStream ois = new ObjectInputStream(fis)) {

        // Read each profile in the time ranges from the file
        for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
            // Filter threads based on the time range
            List<Thread> threads = Thread.getAllThreads();
            for (Thread thread : threads) {
                if (timeRange.isThreadActive(thread)) {
                    // Create a ThreadSnapshot and add it to the list
                    ThreadSnapshot threadSnapshot = new ThreadSnapshot(thread.getName(), thread.getState());
                    threadSnapshots.add(threadSnapshot);
                }
            }
        }

    } catch (ClassNotFoundException | ClassNotFoundException | IOException e) {
        e.printStackTrace();
        throw new IOException("Error reading from file or parsing thread snapshots", e);
    }

    return threadSnapshots;
}

